using System;
using System.Globalization;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class PassengerWorldTests
    {
        static PassengerOptions Options()=>PassengerOptions.Defaults();
        static WalletData Start(bool limo=false){var w=new WalletData{Bank=10000,Cash=123};Assert.True(PassengerTransactions.Begin(w,"ride",limo,Options(),()=>{}));return w;}
        [Theory] [InlineData(null)] [InlineData("")] [InlineData(" ")]
        public void MissingReceiptIdsAreRejectedWithoutMutation(string id){var w=new WalletData{Bank=10000,Passenger=new PassengerData()};Assert.False(PassengerTransactions.Board(w,id,()=>throw new Exception()));Assert.False(PassengerTransactions.Checkpoint(w,id,15000,()=>throw new Exception()));Assert.False(PassengerTransactions.Finish(w,id,"interrupted",()=>throw new Exception()));Assert.Equal(10000,w.Bank);Assert.Null(w.Passenger.Pending);}
        [Fact] public void DefaultsAreUsableAndWorldIsOptIn(){Assert.True(Options().Valid);var world=WorldOptions.Defaults();Assert.True(world.Valid);Assert.Equal("Off",world.Mode);Assert.False(world.SyncClock);Assert.Equal(-118.24167,world.Longitude);}
        [Theory] [InlineData(false,0,2)] [InlineData(false,14999,2)] [InlineData(false,15000,7)] [InlineData(false,30000,12)] [InlineData(true,0,150)] [InlineData(true,15000,151)] [InlineData(true,30000,152)]
        public void DisplayAndSettlementUseSameFare(bool limo,int elapsed,int expected)=>Assert.Equal(expected,PassengerRules.Fare(limo,elapsed,limo?2000:500));
        [Fact] public void FareCannotExceedReservedBudget(){Assert.Equal(500,PassengerRules.Fare(false,3600000,500));Assert.Equal(150,PassengerRules.Fare(true,3600000,150));}
        [Theory] [InlineData(-1,500)] [InlineData(3600001,500)] [InlineData(0,1)]
        public void InvalidFareInputRejected(int elapsed,int budget)=>Assert.Throws<ArgumentOutOfRangeException>(()=>PassengerRules.Fare(false,elapsed,budget));
        [Fact] public void ReserveAndCancelBeforeBoardingReturnsAll(){var w=Start();Assert.Equal(9500,w.Bank);Assert.Equal(123,w.Cash);Assert.Equal(0,w.Passenger.Pending.Fare);Assert.True(PassengerTransactions.Finish(w,"ride","cancelled",()=>{}));Assert.Equal(10000,w.Bank);Assert.Equal(0,w.Passenger.Spent);Assert.Null(w.Passenger.Pending);}
        [Fact] public void BoardedRideRefundsOnlyUnusedBudget(){var w=Start();Assert.True(PassengerTransactions.Board(w,"ride",()=>{}));Assert.True(PassengerTransactions.Checkpoint(w,"ride",15000,()=>{}));Assert.True(PassengerTransactions.Finish(w,"ride","completed",()=>{}));Assert.Equal(9993,w.Bank);Assert.Equal(7,w.Passenger.Spent);Assert.Equal(123,w.Cash);Assert.Equal(7,w.Passenger.History.Single().Fare);}
        [Fact] public void LimoPriceIsConsistentAtPayment(){var w=Start(true);PassengerTransactions.Board(w,"ride",()=>{});PassengerTransactions.Checkpoint(w,"ride",15000,()=>{});PassengerTransactions.Finish(w,"ride","completed",()=>{});Assert.Equal(9849,w.Bank);Assert.Equal(151,w.Passenger.Spent);}
        [Fact] public void BeginAndBoardReplayDoNotSaveOrWithdrawAgain(){var w=Start();Assert.True(PassengerTransactions.Begin(w,"ride",false,Options(),()=>throw new Exception()));PassengerTransactions.Board(w,"ride",()=>{});Assert.True(PassengerTransactions.Board(w,"ride",()=>throw new Exception()));Assert.Equal(9500,w.Bank);Assert.False(PassengerTransactions.Begin(w,"other",false,Options(),()=>throw new Exception()));}
        [Fact] public void CompletionReplayCannotRefundTwice(){var w=Start();PassengerTransactions.Board(w,"ride",()=>{});Assert.True(PassengerTransactions.Finish(w,"ride","interrupted",()=>{}));Assert.True(PassengerTransactions.Finish(w,"ride","interrupted",()=>throw new Exception()));Assert.False(PassengerTransactions.Finish(w,"ride","completed",()=>throw new Exception()));Assert.Equal(9998,w.Bank);}
        [Fact] public void RecoveryCannotCreateAFreeCompletedTrip(){var w=Start();Assert.False(PassengerTransactions.Finish(w,"ride","completed",()=>throw new Exception()));Assert.True(PassengerTransactions.Finish(w,"ride","interrupted",()=>{}));Assert.Equal(10000,w.Bank);}
        [Theory] [InlineData(-1)] [InlineData(1)] [InlineData(14999)] [InlineData(15001)] [InlineData(1800001)]
        public void MeterAcceptsOnlyExactDurableSteps(int elapsed){var w=Start();PassengerTransactions.Board(w,"ride",()=>{});Assert.False(PassengerTransactions.Checkpoint(w,"ride",elapsed,()=>throw new Exception()));Assert.Equal(0,w.Passenger.Pending.Elapsed);}
        [Fact] public void MeterCannotRewindOrAdvanceBeforeBoarding(){var w=Start();Assert.False(PassengerTransactions.Checkpoint(w,"ride",15000,()=>{}));PassengerTransactions.Board(w,"ride",()=>{});Assert.True(PassengerTransactions.Checkpoint(w,"ride",15000,()=>{}));Assert.False(PassengerTransactions.Checkpoint(w,"ride",0,()=>{}));Assert.True(PassengerTransactions.Checkpoint(w,"ride",15000,()=>throw new Exception()));}
        [Theory] [InlineData("begin")] [InlineData("board")] [InlineData("checkpoint")] [InlineData("finish")] [InlineData("template")]
        public void DiskFailureRollsBackEntireBookAndBank(string operation)
        {
            var w=operation=="begin"?new WalletData{Bank=10000}:Start();if(operation=="checkpoint")PassengerTransactions.Board(w,"ride",()=>{});string before=JsonConvert.SerializeObject(w);Action fail=()=>throw new InvalidOperationException("disk");
            Assert.Throws<InvalidOperationException>(()=>{if(operation=="begin")PassengerTransactions.Begin(w,"ride",false,Options(),fail);else if(operation=="board")PassengerTransactions.Board(w,"ride",fail);else if(operation=="checkpoint")PassengerTransactions.Checkpoint(w,"ride",15000,fail);else if(operation=="finish")PassengerTransactions.Finish(w,"ride","interrupted",fail);else {PassengerTransactions.Finish(w,"ride","cancelled",()=>{});before=JsonConvert.SerializeObject(w);PassengerTransactions.Template(w,null,fail);}});
            Assert.Equal(before,JsonConvert.SerializeObject(w));
        }
        [Fact] public void BankOverflowKeepsEscrowPending(){var w=Start();w.Bank=int.MaxValue;Assert.False(PassengerTransactions.Finish(w,"ride","cancelled",()=>throw new Exception()));Assert.NotNull(w.Passenger.Pending);Assert.Equal(int.MaxValue,w.Bank);}
        [Fact] public void InsufficientBankAndInvalidBookArePreserved(){var w=new WalletData{Bank=499};Assert.False(PassengerTransactions.Begin(w,"ride",false,Options(),()=>throw new Exception()));Assert.Null(w.Passenger);w.Bank=10000;w.Passenger=new PassengerData{History=null};Assert.False(PassengerTransactions.Begin(w,"ride",false,Options(),()=>throw new Exception()));Assert.Null(w.Passenger.History);}
        [Fact] public void PaidOptionsAreSnapshotAndUnknownMetadataSurvives(){var o=Options();o.Extra=new System.Collections.Generic.Dictionary<string,JToken>{{"Future",42}};var w=new WalletData{Bank=10000};PassengerTransactions.Begin(w,"ride",false,o,()=>{});o.TaxiBudget=999;Assert.Equal(500,w.Passenger.Pending.Budget);PassengerTransactions.Board(w,"ride",()=>{});Assert.Equal(42,(int)w.Passenger.Pending.Options.Extra["Future"]);}
        [Fact] public void HistoryIsBoundedAndLifetimeChargesRetained(){var w=new WalletData{Bank=10000};for(int i=0;i<40;i++){PassengerTransactions.Begin(w,"r"+i,false,Options(),()=>{});PassengerTransactions.Board(w,"r"+i,()=>{});PassengerTransactions.Finish(w,"r"+i,"completed",()=>{});}Assert.True(w.Passenger.Valid);Assert.Equal(32,w.Passenger.History.Count);Assert.Equal(40,w.Passenger.Trips);Assert.Equal(80,w.Passenger.Spent);Assert.Equal(9920,w.Bank);}
        [Theory] [InlineData(100,90,true,10)] [InlineData(100,90,false,0)] [InlineData(2000,0,true,0)] [InlineData(0,100,true,0)] [InlineData(-2147483640,2147483640,true,16)]
        public void PauseStallAndTimerWrap(int now,int previous,bool active,int expected)=>Assert.Equal(expected,PassengerRules.Delta(now,previous,active));
        [Theory] [InlineData(true,true,0f,10f,true)] [InlineData(false,true,0f,0f,false)] [InlineData(true,false,0f,0f,false)] [InlineData(true,true,1f,0f,false)] [InlineData(true,true,0f,10.1f,false)] [InlineData(true,true,float.NaN,0f,false)]
        public void ArrivalRequiresStoppedPassenger(bool passenger,bool usable,float speed,float distance,bool expected)=>Assert.Equal(expected,PassengerRules.Arrival(passenger,usable,speed,distance));
        [Theory] [InlineData(0,"ExtraSunny")] [InlineData(1,"Clear")] [InlineData(2,"Clouds")] [InlineData(3,"Overcast")] [InlineData(45,"Foggy")] [InlineData(48,"Overcast")] [InlineData(51,"Raining")] [InlineData(57,"Raining")] [InlineData(67,"Raining")] [InlineData(82,"Raining")] [InlineData(71,"Snowlight")] [InlineData(73,"Snowing")] [InlineData(75,"Blizzard")] [InlineData(85,"Snowing")] [InlineData(86,"Blizzard")] [InlineData(95,"ThunderStorm")] [InlineData(99,"ThunderStorm")]
        public void WmoCodesMapToSupportedWeather(int code,string expected)=>Assert.Equal(expected,WorldRules.FromCode(code));
        [Theory] [InlineData("{}")] [InlineData("{\"current_weather\":{}}")] [InlineData("{\"current_weather\":{\"weathercode\":999,\"temperature\":20}}")] [InlineData("{\"current_weather\":{\"weathercode\":1,\"temperature\":200}}")] [InlineData("{\"current_weather\":{\"weathercode\":\"1\",\"temperature\":20}}")] [InlineData("not json")]
        public void BadWeatherResponseIsRejected(string json)=>Assert.ThrowsAny<Exception>(()=>WorldRules.Parse(json));
        [Fact] public void WeatherReadingAndFahrenheit(){var r=WorldRules.Parse("{\"current_weather\":{\"weathercode\":61,\"temperature\":20.5},\"untrusted\":\"ignore\"}");Assert.Equal("Raining",r.Weather);Assert.Equal(20.5,r.Celsius);Assert.Equal(32,WorldRules.Temperature(0,true));Assert.Equal(20.5,WorldRules.Temperature(20.5,false));Assert.Throws<FormatException>(()=>WorldRules.Parse(new string('x',65537)));}
        [Fact] public void FixedApiUrlUsesInvariantNumbers(){var old=CultureInfo.CurrentCulture;try{CultureInfo.CurrentCulture=new CultureInfo("pt-BR");string url=WorldRules.Url(-23.55,-46.63);Assert.StartsWith("https://api.open-meteo.com/v1/forecast?",url);Assert.Contains("latitude=-23.55",url);Assert.Contains("longitude=-46.63",url);}finally{CultureInfo.CurrentCulture=old;}Assert.Throws<ArgumentException>(()=>WorldRules.Url(double.NaN,0));Assert.Throws<ArgumentException>(()=>WorldRules.Url(91,0));}
        [Theory] [InlineData("Clear")] [InlineData("Raining")] [InlineData("Overcast")] [InlineData("ThunderStorm")]
        public void DynamicTransitionsStaySupportedAndAvoidAbruptSnow(string current){for(int i=0;i<100;i++){string next=WorldRules.Next(current,i);Assert.Contains(next,WorldRules.Weathers);Assert.DoesNotContain("Snow",next);}Assert.Throws<ArgumentOutOfRangeException>(()=>WorldRules.Next(current,100));}
        [Theory] [InlineData("badmode")] [InlineData("badweather")] [InlineData("latitude")] [InlineData("longitude")] [InlineData("refresh")] [InlineData("dynamic")] [InlineData("location")]
        public void InvalidWorldPreferencesNeverSave(string bad){var current=WorldOptions.Defaults();var next=WorldRules.Copy(current);if(bad=="badmode")next.Mode="scripts";if(bad=="badweather")next.Weather="x";if(bad=="latitude")next.Latitude=double.NaN;if(bad=="longitude")next.Longitude=181;if(bad=="refresh")next.RefreshSeconds=1;if(bad=="dynamic")next.DynamicSeconds=0;if(bad=="location")next.Location="a\nb";Assert.False(WorldRules.Configure(ref current,next,_=>throw new Exception()));Assert.Equal("Off",current.Mode);}
        [Fact] public void WorldPreferenceFailureDoesNotActivateMode(){var current=WorldOptions.Defaults();var old=current;var next=WorldRules.Copy(current);next.Mode="Real";Assert.Throws<InvalidOperationException>(()=>WorldRules.Configure(ref current,next,_=>throw new InvalidOperationException()));Assert.Same(old,current);Assert.Equal("Off",current.Mode);}
        [Fact] public void PreferenceCommitClonesAndRetainsFutureFields(){var current=WorldOptions.Defaults();var next=WorldRules.Copy(current);next.Mode="Dynamic";next.Extra=new System.Collections.Generic.Dictionary<string,JToken>{{"Future",true}};Assert.True(WorldRules.Configure(ref current,next,n=>Assert.Equal("Dynamic",n.Mode)));next.Mode="Off";Assert.Equal("Dynamic",current.Mode);Assert.True((bool)current.Extra["Future"]);}
    }
}
